var GTS = GTS || {}; GTS.FossilCleaning  = GTS.FossilCleaning || {};
var Imported = Imported || {}; Imported["GreenTreeStudios_FossilCleaning"] = 1.00;

(($_$) => {
    const NAMESPACE   = 'FossilCleaning';
    const PLUGIN_NAME = 'GTS_' + NAMESPACE;

    function getPluginParameters() {var a = document.currentScript || (function() { var b = document.getElementsByTagName('script'); return b[b.length - 1]; })(); return PluginManager.parameters(a.src.substring((a.src.lastIndexOf('/') + 1), a.src.indexOf('.js')));} $_$.params = getPluginParameters();

    ['BGM'].forEach(function(v){
        $_$.params[v] = $_$.params[v] || '""';
        $_$.params[v] = JSON.parse($_$.params[v]);
    });

    $_$.bgm = $_$.params['BGM'];
    $_$.fossilRock = $_$.params['RockTemplates:ArrayStruct'];
    $_$.rockDrawCode = $_$.params['RockDrawCode:func'];
    $_$.fossil = $_$.params['Templates:ArrayStruct'];
    $_$.fossilDrawCode = $_$.params['FossilDrawCode:func'];
    $_$.holeTiles = $_$.params['HoleMaskTile'];
    $_$.cleaningIMG = $_$.params['cleaningBackground'];



    //-----------------------------------------------------------------------------
    // FossilCleaningManager
    //
    // The static class that assists with the Slot Game progress.

    function FossilCleaningManager() {
        throw new Error("This is a static class");
    }

    FossilCleaningManager.setup = function() {

    };

    FossilCleaningManager.saveBgmAndBgs = function() {
        this._mapBgm = AudioManager.saveBgm();
        this._mapBgs = AudioManager.saveBgs();
    };

    FossilCleaningManager.replayBgmAndBgs = function() {
        if (this._mapBgm) { 
            AudioManager.replayBgm(this._mapBgm);
        } else {
            AudioManager.stopBgm();
        }
        if (this._mapBgs) {
            AudioManager.replayBgs(this._mapBgs);
        }
    };

    FossilCleaningManager.playBgm = function(audio) {
        audio = audio || $_$.bgm || {};
        console.log(audio);
        AudioManager.playBgm(audio);
        AudioManager.stopBgs();
    };

    FossilCleaningManager.stopAudioOnStart = function(audio) {
        audio = audio || GTS.FossilCleaning.bgm || {};
        if (!AudioManager.isCurrentBgm(audio)) {
            AudioManager.stopBgm();
        };
        AudioManager.stopBgs();
        AudioManager.stopMe();
        AudioManager.stopSe();
    };

    //-----------------------------------------------------------------------------
    // FossilDamageSprite
    //
    function FossilDamageSprite() {
        this.initialize.apply(this, arguments);
    }

    FossilDamageSprite.prototype = Object.create(Sprite.prototype);
    FossilDamageSprite.prototype.constructor = FossilDamageSprite;

    FossilDamageSprite.prototype.initialize = function (bitmap) {
        Sprite.prototype.initialize.call(this, bitmap);
    };

    //-----------------------------------------------------------------------------
    // CleaningBackgroundSprite
    //

    function CleaningBackgroundSprite() {
        this.initialize.apply(this, arguments);
    }

    CleaningBackgroundSprite.prototype = Object.create(Sprite.prototype);
    CleaningBackgroundSprite.prototype.constructor = CleaningBackgroundSprite;

    CleaningBackgroundSprite.prototype.initialize = function (bitmap) {
        Sprite.prototype.initialize.call(this, bitmap);
    };


    //-----------------------------------------------------------------------------
    // FossilSprite
    //

    function FossilSprite() {
        this.initialize.apply(this, arguments);
    }

    FossilSprite.prototype = Object.create(Sprite.prototype);
    FossilSprite.prototype.constructor = FossilSprite;

    FossilSprite.prototype.initialize = function (bitmap) {
        Sprite.prototype.initialize.call(this, bitmap);
    };

    //-----------------------------------------------------------------------------
    // RockSprite
    //

    function RockSprite() {
        this.initialize.apply(this, arguments);
    }

    RockSprite.prototype = Object.create(Sprite.prototype);
    RockSprite.prototype.constructor = RockSprite;

    RockSprite.prototype.initialize = function (bitmap) {
        Sprite.prototype.initialize.call(this, bitmap);
    };

    //------------------------------------------------------------------------------
    // Scene FossilCleaning
    //

    function Scene_FossilCleaning() {
        this.initialize(...arguments);
    }

    Scene_FossilCleaning.prototype = Object.create(Scene_MenuBase.prototype);
    Scene_FossilCleaning.prototype.constructor = Scene_FossilCleaning;

    $_$['Scene_FossilCleaning.prototype.isReady'] = Scene_FossilCleaning.prototype.isReady;
    Scene_FossilCleaning.prototype.isReady = function() {
        return $_$['Scene_FossilCleaning.prototype.isReady'].apply(this, arguments) && this._imagesLoaded >= this._imagesLoadCount;
    };

    Scene_FossilCleaning.prototype.imageLoaded = function () {
        this._imagesLoaded++;
    };

    Scene_FossilCleaning.prototype.initialize = function () {
        this._imagesLoaded = 0;
        this._imagesLoadCount = 2;

        $_$._cleaningBackgroundBitmap = ImageManager.loadBitmap($_$.cleaningIMG);
        $_$._cleaningBackgroundBitmap.addLoadListener(this.imageLoaded.bind(this)); 
        $_$._fossilBitmap = ImageManager.loadBitmap();
        $_$._fossilBitmap.addLoadListener(this.imageLoaded.bind(this));     
        $_$._rockBitmap = ImageManager.loadBitmap();
        $_$._rockBitmap.addLoadListener(this.imageLoaded.bind(this));

        Scene_MenuBase.prototype.initialize.call(this);
    };

    Scene_FossilCleaning.prototype.create = function () {
        this.createBackground();
        this.createFossil();
        this.createRock();
    };

    Scene_FossilCleaning.prototype.createBackground = function () {     
        this._backgroundSprite = new CleaningBackgroundSprite($_$._cleaningBackgroundBitmap);
        this.addChild(this._backgroundSprite);
    };

    Scene_FossilCleaning.prototype.createFossil = function() {
        this._fossilPieces = [];

        // sprite settings
        const cellSize = 24;
        const cols  = $_$._fossilBitmap.width  / cellSize;
        const rows  = $_$._fossilBitmap.height / cellSize;

        for (var i = 0; i < cols*rows; i++) {
            var row = Math.floor(i / cols);
            var col = i % cols;
            this._fossilPieces[i] = new FossilSprite($_$._fossilBitmap);
            this._fossilPieces[i].setFrame(col*cellSize, row*cellSize, cellSize, cellSize);
            this._fossilPieces[i].x = col * cellSize;
            this._fossilPieces[i].y = row * cellSize;
            this._fossilPieces[i].visible = false;
            this.addChild(this._fossilPieces[i]);
        };

    }

    Scene_FossilCleaning.prototype.createRock = function() {
        this._rockPieces = [];

        // sprite settings
        const cellSize = 24;
        const cols  = $_$._rockBitmap.width  / cellSize;
        const rows  = $_$._rockBitmap.height / cellSize;

        for (var i = 0; i < cols*rows; i++) {
            var row = Math.floor(i / cols);
            var col = i % cols;
            this._rockPieces[i] = new RockSprite($_$._rockBitmap);
            this._rockPieces[i].setFrame(col*cellSize, row*cellSize, cellSize, cellSize);
            this._rockPieces[i].x = col * cellSize;
            this._rockPieces[i].y = row * cellSize;
            this._rockPieces[i].visible = false;
            this.addChild(this._rockPieces[i]);
        }
    };

    //-----------------------------------------------------------------------------
    // GTS.FossilsMZ
    //-----------------------------------------------------------------------------

    GTS.FossilCleaning.Play = function(){
        FossilCleaningManager.saveBgmAndBgs();
        FossilCleaningManager.stopAudioOnStart();

        SceneManager.push(Scene_FossilCleaning); 
    };

})(GTS.FossilCleaning, this);
